mapper.select:
SELECT FROM inquiry_invite WHERE supplier_tenant_id = #{supplierTenantId} AND is_deleted = 0
AND invite_status = #{inviteStatus}
ORDER BY invited_at DESC

SELECT FROM inquiry_invite WHERE inquiry_id IN
#{id}
AND supplier_tenant_id = #{supplierTenantId} AND is_deleted = 0

SELECT inquiry_id AS inquiryId, invite_status AS inviteStatus, COUNT(*) AS supplierCount FROM inquiry_invite WHERE inquiry_id IN
#{id}
AND is_deleted = 0 GROUP BY inquiry_id, invite_status

mapper.update:
UPDATE inquiry_invite
SET invite_status = 'pending', responded_at = NULL, decline_reason = NULL, update_by = #{updateBy}
WHERE id = #{id} AND invite_status = 'declined' AND is_deleted = 0

mapper.select:
SELECT DISTINCT q.supplier_tenant_id
FROM quote q
JOIN inquiry i ON q.inquiry_id = i.id AND i.is_deleted = 0
WHERE i.buyer_tenant_id = #{buyerTenantId}
  AND i.requirement_id = #{requirementId}
  AND q.is_winning = 1
  AND q.is_deleted = 0
  AND q.supplier_tenant_id IN
#{sid}

SELECT DISTINCT ii.supplier_tenant_id
FROM inquiry_invite ii
JOIN inquiry i ON ii.inquiry_id = i.id AND i.is_deleted = 0
WHERE i.buyer_tenant_id = #{buyerTenantId}
  AND i.requirement_id = #{requirementId}
  AND i.status IN ('open', 'quoting')
  AND ii.is_deleted = 0
  AND ii.supplier_tenant_id IN
#{sid}
